import java.util.*;

class Solution {
    public int minCancelled(int[][] shows) {
        int[][] s = shows.clone();
        Arrays.sort(s, (a, b) -> Integer.compare(a[1], b[1]));   // earliest end first
        int kept = 0;
        long lastEnd = Long.MIN_VALUE;
        for (int[] sh : s) {
            if (sh[0] >= lastEnd) {     // fits after the last kept show
                kept++;
                lastEnd = sh[1];
            }
        }
        return s.length - kept;
    }
}

