class Solution:
    def minCancelled(self, shows: List[List[int]]) -> int:
        kept, last = 0, -inf
        for s, e in sorted(shows, key=lambda x: x[1]):
            if s >= last:
                kept += 1; last = e
        return len(shows) - kept

