function minCancelled(shows) {
  const a = shows.slice().sort((p, q) => p[1] - q[1]);
  let kept = 0, last = -Infinity;
  for (const [s, e] of a) if (s >= last) { kept++; last = e; }
  return shows.length - kept;
}
